//! Original fixed-basis92E570 outputs and92FAD2angle-index conversion.
//! Initializer identity is explicit; caller orientation-vector mapping is external.
#[derive(Clone,Copy)] pub enum Initializer {At92910F,At92923B,At929373}
pub fn angle_index(angle:f32)->usize {
 let integer=if !angle.is_finite() || angle>=2147483648. || angle< -2147483648. {i32::MIN}else{angle.trunc() as i32};
 integer.rem_euclid(360) as usize
}
pub fn axes(initializer:Initializer,angle:f32)->[u32;6] {
 let source=match initializer {Initializer::At92910F=>0,Initializer::At92923B=>1,Initializer::At929373=>2};
 TABLES[source][angle_index(angle)]
}
/// Actual original manager vector order: camera0, fixed initializer1/2/3.
/// Camera0 is supplied by a fresh view-dependent producer, never this fixed table.
pub fn selected_fixed(orientation:u32,angle:f32)->Result<[u32;6],&'static str> {
 let initializer=match orientation {1=>Initializer::At92910F,2=>Initializer::At92923B,3=>Initializer::At929373,
  0=>return Err("fresh native camera orientation table required"),_=>return Err("native orientation outside four-table vector")};
 Ok(axes(initializer,angle))
}
/// Native four-table selection, with the current camera required for orientation0.
pub fn selected(orientation:u32,angle:f32,view:Option<[f32;16]>)->Result<[u32;6],&'static str> {
 if orientation!=0 {return selected_fixed(orientation,angle);}
 let view=view.ok_or("fresh native camera view required")?;
 let a=openleague_core::native_simple_type0_quad::axes(view,angle).map_err(|_|"native camera axes rejected")?;
 Ok([a.a[0].to_bits(),a.a[1].to_bits(),a.a[2].to_bits(),a.b[0].to_bits(),a.b[1].to_bits(),a.b[2].to_bits()])
}
